const script="(()=>{\n\"use strict\";\n/* Búsqueda y CAPTCHA equivalentes en móvil y escritorio. */\nlet observer=null,attempting=false;\nconst input=()=>document.getElementById(\"inputBusqueda\");\nconst captcha=()=>document.getElementById(\"slideCaptcha\");\nfunction syncSearch(){\n const field=input();\n if(field){\n  if(field.getAttribute(\"placeholder\")!==\"Buscar\")field.setAttribute(\"placeholder\",\"Buscar\");\n  if(field.getAttribute(\"aria-label\")!==\"Buscar\")field.setAttribute(\"aria-label\",\"Buscar\");\n }\n const box=document.getElementById(\"googleSearchBox\");\n if(box){\n  box.querySelectorAll(\".search-leading-icon\").forEach(e=>e.remove());\n  const btn=box.querySelector(\".google-search-button\");\n  if(btn&&(btn.querySelector(\"svg\")||btn.textContent.trim()!==\"Buscar\"))btn.textContent=\"Buscar\";\n  const photo=box.querySelector(\"#uhzBusquedaFoto .uhz-photo-icon\");\n  if(photo&&!photo.dataset.uhzCameraSet){\n   photo.innerHTML='<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 7h3l1.7-2h6.6L17 7h3a1.5 1.5 0 0 1 1.5 1.5v10A1.5 1.5 0 0 1 20 20H4a1.5 1.5 0 0 1-1.5-1.5v-10A1.5 1.5 0 0 1 4 7Z\"/><circle cx=\"12\" cy=\"13\" r=\"3.2\"/></svg>';\n   photo.dataset.uhzCameraSet=\"1\";\n  }\n }\n const note=document.getElementById(\"uhzModoIANota\");\n if(note){\n  const composer=document.querySelector(\"#buscador .uhz-search-composer\");\n  if(composer&&box&&note.parentElement===composer&&note.nextElementSibling!==box)composer.insertBefore(note,box);\n  if(note.textContent.trim()===\"Buscar contenido\")note.textContent=\"\";\n }\n}\nfunction status(mode){\n const card=captcha();if(!card)return;\n const badge=card.querySelector(\".captcha-shield\");\n const row=card.querySelector(\"#estadoParticula\");\n if(mode===\"ok\"){\n  if(card.classList.contains(\"uhz-captcha-failed\"))card.classList.remove(\"uhz-captcha-failed\");\n  if(badge&&badge.textContent!==\"✓\")badge.textContent=\"✓\";\n  if(row&&row.textContent!==\"Verificación correcta\")row.textContent=\"Verificación correcta\";\n }else if(mode===\"fail\"){\n  if(card.classList.contains(\"verified\"))return status(\"ok\");\n  if(!card.classList.contains(\"uhz-captcha-failed\"))card.classList.add(\"uhz-captcha-failed\");\n  if(badge&&badge.textContent!==\"✕\")badge.textContent=\"✕\";\n  if(row&&row.textContent!==\"Verificación incorrecta\")row.textContent=\"Verificación incorrecta\";\n  const text=card.querySelector(\"#slideText\");\n  if(text&&text.textContent.trim()!==\"Intenta de nuevo\")text.textContent=\"Intenta de nuevo\";\n }else{\n  if(card.classList.contains(\"uhz-captcha-failed\"))card.classList.remove(\"uhz-captcha-failed\");\n  if(badge&&badge.textContent!==\"\")badge.textContent=\"\";\n }\n}\nfunction syncStatus(){\n const card=captcha();if(!card)return;\n if(card.classList.contains(\"verified\"))status(\"ok\");\n else if(card.classList.contains(\"uhz-captcha-failed\"))status(\"fail\");\n else status(\"pending\");\n}\nfunction startAttempt(e){\n const card=captcha();\n if(!card||card.classList.contains(\"verified\"))return;\n if(e.type===\"pointerdown\"&&e.button!==0)return;\n attempting=true;\n status(\"pending\");\n const slide=card.querySelector(\"#slideText\");\n if(slide&&slide.textContent.trim()===\"Intenta de nuevo\")slide.textContent=\"Mantén presionado y desliza\";\n}\nfunction endAttempt(){\n if(!attempting)return;\n attempting=false;\n window.setTimeout(()=>{\n  const card=captcha();if(!card)return;\n  if(card.classList.contains(\"verified\"))status(\"ok\");\n  else status(\"fail\");\n },55);\n}\nfunction setupCaptcha(){\n const card=captcha(),box=document.getElementById(\"googleSearchBox\");\n if(!card||card.dataset.uhzCaptchaMobile===\"1\")return;\n card.dataset.uhzCaptchaMobile=\"1\";\n const heading=card.querySelector(\".human-check-head strong\");\n if(heading)heading.textContent=\"CAPTCHA · Verificación humana\";\n const instruction=card.querySelector(\".human-check-head span\");\n const control=card.querySelector(\".captcha-control\");\n if(instruction&&control){\n  instruction.classList.add(\"uhz-captcha-instructions\");\n  instruction.textContent=\"Desliza hacia la derecha para verificar.\";\n  control.after(instruction);\n }\n const shield=card.querySelector(\".captcha-shield\");if(shield)shield.textContent=\"\";\n const track=card.querySelector(\"#slideTrack\"),handle=card.querySelector(\"#sliderHandle\");\n if(handle){\n  handle.addEventListener(\"pointerdown\",startAttempt,{capture:true});\n  handle.addEventListener(\"touchstart\",startAttempt,{passive:true,capture:true});\n  handle.addEventListener(\"mousedown\",startAttempt,{capture:true});\n }\n document.addEventListener(\"pointerup\",endAttempt,{passive:true});\n document.addEventListener(\"pointercancel\",endAttempt,{passive:true});\n document.addEventListener(\"touchend\",endAttempt,{passive:true});\n document.addEventListener(\"mouseup\",endAttempt,{passive:true});\n if(track)track.addEventListener(\"keyup\",syncStatus);\n const stateObserver=new MutationObserver(syncStatus);\n stateObserver.observe(card,{attributes:true,attributeFilter:[\"class\"]});\n syncStatus();\n}\n\nfunction setupMobileMenu(){\n const details=document.querySelector(\"#uhz-native-head details\");\n if(!details||details.dataset.uhzMenuReady)return;\n details.dataset.uhzMenuReady=\"1\";\n const picker=()=>document.querySelector(\"#uhz-global-header .uhzg-theme-picker\");\n function currentTheme(){\n  const data=document.documentElement.dataset.uhzTheme;\n  if(data===\"colorful\"||data===\"dark\")return data;\n  try{return localStorage.getItem(\"uhz_header_theme\")===\"dark\"?\"dark\":\"colorful\"}catch{return\"colorful\"}\n }\n function sync(){\n  const theme=currentTheme();\n  details.querySelectorAll(\".uhz-theme-choice\").forEach(btn=>btn.setAttribute(\"aria-pressed\",String(btn.dataset.uhzChoice===theme)));\n }\n details.addEventListener(\"toggle\",()=>{if(details.open)sync()});\n details.addEventListener(\"click\",event=>{\n  const btn=event.target.closest(\".uhz-theme-choice\");\n  if(!btn)return;\n  const theme=btn.dataset.uhzChoice;\n  if(![\"colorful\",\"dark\"].includes(theme))return;\n  const select=picker();\n  if(select){select.value=theme;select.dispatchEvent(new Event(\"change\",{bubbles:true}))}\n  else{\n   const dark=theme===\"dark\";\n   document.documentElement.dataset.uhzTheme=theme;\n   document.documentElement.dataset.theme=dark?\"dark\":\"light\";\n   document.documentElement.style.colorScheme=dark?\"dark\":\"light\";\n   document.body.classList.toggle(\"dark-mode\",dark);\n   document.body.classList.toggle(\"modo-oscuro\",dark);\n   try{localStorage.setItem(\"uhz_header_theme\",theme);localStorage.setItem(\"modo_oscuro_univershzrw\",dark?\"1\":\"0\")}catch{}\n   window.dispatchEvent(new CustomEvent(\"uhz:theme-change\",{detail:{theme}}));\n  }\n  sync();\n });\n document.addEventListener(\"click\",event=>{if(details.open&&!details.contains(event.target))details.open=false});\n document.addEventListener(\"keydown\",event=>{if(event.key===\"Escape\"&&details.open){details.open=false;details.querySelector(\"summary\")?.focus()}});\n window.addEventListener(\"uhz:theme-change\",sync);\n sync();\n}\n\n\nfunction setupProfileShortcut(){\n const header=document.getElementById(\"uhz-native-head\");\n const link=header?.querySelector(\".uhz-app-profile-link\");\n if(!link||link.dataset.uhzAccountReady)return;\n link.dataset.uhzAccountReady=\"1\";\n const icon=link.querySelector(\".uhz-app-profile-icon\");\n const STAR='<svg viewBox=\"0 0 40 40\" width=\"26\" height=\"26\" fill=\"none\" aria-hidden=\"true\"><path d=\"M20 4.5c1.9 8.6 6.9 13.6 15.5 15.5-8.6 1.9-13.6 6.9-15.5 15.5C18.1 26.9 13.1 21.9 4.5 20 13.1 18.1 18.1 13.1 20 4.5Z\" fill=\"#eaf7ff\"/></svg>';\n let lastStatus=null,lastSrc=\"\";\n function sync(){\n  const old=document.querySelector(\"#uhz-global-header .uhzg-account\");\n  const signed=Boolean(old?.classList.contains(\"is-member\"));\n  const avatar=old?.querySelector(\".uhzg-avatar img\");\n  const src=signed&&avatar?.getAttribute(\"src\")||\"\";\n  if(lastStatus===signed&&lastSrc===src)return;\n  lastStatus=signed;lastSrc=src;\n  link.classList.toggle(\"is-signed-in\",signed);\n  link.href=signed?\"/mi-cuenta\":\"/iniciar-sesion\";\n  link.setAttribute(\"aria-label\",signed?\"Abrir Mi cuenta\":\"Entrar\");\n  link.title=signed?\"Mi cuenta\":\"Entrar\";\n  const label=link.querySelector(\".uhz-app-enter-text\");\n  if(label)label.textContent=signed?\"\":\"Entrar\";\n  if(!icon)return;\n  if(!signed||!src){icon.innerHTML=STAR;return}\n  const img=document.createElement(\"img\");\n  img.alt=\"\";\n  img.referrerPolicy=\"same-origin\";\n  img.loading=\"eager\";\n  img.addEventListener(\"error\",()=>{icon.innerHTML=STAR},{once:true});\n  img.src=src;\n  icon.replaceChildren(img);\n }\n function observeAccount(){\n  const old=document.querySelector(\"#uhz-global-header .uhzg-account\");\n  if(!old)return false;\n  const changes=new MutationObserver(sync);\n  changes.observe(old,{attributes:true,attributeFilter:[\"class\"],subtree:true,childList:true});\n  sync();\n  return true;\n }\n sync();\n if(!observeAccount()){\n  const watcher=new MutationObserver(()=>{if(observeAccount())watcher.disconnect()});\n  watcher.observe(document.documentElement,{childList:true,subtree:true});\n }\n window.addEventListener(\"focus\",sync);\n window.addEventListener(\"pageshow\",sync);\n}\n\n\nfunction enhanceUnivershzrwBrand(){\n  if(!window.matchMedia(\"(min-width:801px)\").matches)return;\n  const brand=document.querySelector(\"#uhz-global-header .uhzg-brand\");\n  if(brand)brand.classList.add(\"uhz-animated-u\");\n  const stage=document.querySelector(\"#buscador .search-brand-mini.uhz-brand-stage\");\n  if(!stage||stage.querySelector(\".uhz-quantum-sparks\"))return;\n  const layer=document.createElement(\"div\");\n  layer.className=\"uhz-quantum-sparks\";\n  layer.setAttribute(\"aria-hidden\",\"true\");\n  const tones=[\"#8fe9ff\",\"#65caff\",\"#c5f5ff\",\"#75aaf8\",\"#9cf3eb\"];\n  for(let i=0;i<30;i++){\n    const angle=(i*137.507764)*Math.PI/180;\n    const radius=Math.sqrt((i+.5)/30)*43;\n    const x=50+Math.cos(angle)*radius;\n    const y=49+Math.sin(angle)*radius*.91;\n    const spark=document.createElement(\"i\");\n    spark.style.setProperty(\"--sx\",x.toFixed(2)+\"%\");\n    spark.style.setProperty(\"--sy\",y.toFixed(2)+\"%\");\n    spark.style.setProperty(\"--sz\",(2.5+(i%5)*1.15).toFixed(1)+\"px\");\n    spark.style.setProperty(\"--sd\",(2.8+(i%7)*.55).toFixed(2)+\"s\");\n    spark.style.setProperty(\"--st\",(-((i*17)%39)/10).toFixed(2)+\"s\");\n    spark.style.setProperty(\"--dx\",((i%2?1:-1)*(5+i%11))+\"px\");\n    spark.style.setProperty(\"--sc\",tones[i%tones.length]);\n    layer.appendChild(spark);\n  }\n  stage.prepend(layer);\n}\n\n\n\nfunction setupUhzGooglePresentation(){\n const box=document.getElementById(\"googleSearchBox\");\n if(box)box.dataset.uhzStyleVersion=\"22\";\n const copy=document.querySelector(\"#buscador .search-brand-mini.uhz-brand-stage .uhz-logo-copy\");\n if(!copy||copy.querySelector(\".uhz-signal-network\"))return;\n const root=document.createElementNS(\"http://www.w3.org/2000/svg\",\"svg\");\n root.setAttribute(\"class\",\"uhz-signal-network\");\n root.setAttribute(\"viewBox\",\"0 0 1000 220\");\n root.setAttribute(\"preserveAspectRatio\",\"none\");\n root.setAttribute(\"aria-hidden\",\"true\");\n const ns=\"http://www.w3.org/2000/svg\";\n const values=[110,97,116,90,121,95,117,88,120,95,110];\n const nodes=values.map((y,i)=>({x:87+i*82.5,y:y}));\n const paint=(tag,attrs,parent=root)=>{\n  const el=document.createElementNS(ns,tag);\n  for(const [key,value] of Object.entries(attrs))el.setAttribute(key,String(value));\n  parent.appendChild(el);return el;\n };\n for(let i=0;i<nodes.length-1;i++){\n  const from=nodes[i],to=nodes[i+1];\n  const y=(from.y+to.y)/2+(i%2?-17:17);\n  const d=\"M\"+from.x+\",\"+from.y+\" Q\"+((from.x+to.x)/2)+\",\"+y+\" \"+to.x+\",\"+to.y;\n  const path=paint(\"path\",{d,class:\"uhz-signal-path\",style:\"--delay:\"+(-i*.26)+\"s\"});\n  const signal=paint(\"circle\",{r:2.6,class:\"uhz-signal-glow\"});\n  paint(\"animateMotion\",{dur:(2.8+i%3*.65)+\"s\",begin:(-i*.39)+\"s\",repeatCount:\"indefinite\",path:d},signal);\n }\n for(const [i,j] of [[0,3],[2,5],[4,8],[7,10]]){\n  const p=nodes[i],q=nodes[j];\n  const d=\"M\"+p.x+\",\"+p.y+\" Q\"+((p.x+q.x)/2)+\",40 \"+q.x+\",\"+q.y;\n  paint(\"path\",{d,class:\"uhz-signal-path\",style:\"--delay:\"+(-i*.55)+\"s;opacity:.18\"});\n }\n nodes.forEach((node,i)=>{\n  paint(\"circle\",{cx:node.x,cy:node.y,r:(i%3?3.1:4.1),class:\"uhz-signal-node\",style:\"--delay:\"+(i*.16)+\"s\"});\n });\n copy.prepend(root);\n}\n\nfunction initialize(){\n syncSearch();setupCaptcha();setupMobileMenu();setupProfileShortcut();enhanceUnivershzrwBrand();setupUhzGooglePresentation();\n const box=document.getElementById(\"googleSearchBox\");\n const note=document.getElementById(\"uhzModoIANota\");\n if(box){\n  observer=new MutationObserver(syncSearch);\n  observer.observe(box,{attributes:true,attributeFilter:[\"placeholder\"],childList:true,subtree:true});\n  if(note)observer.observe(note,{childList:true,characterData:true,subtree:true});\n }\n window.addEventListener(\"pageshow\",()=>{syncSearch();syncStatus();enhanceUnivershzrwBrand();setupUhzGooglePresentation()},{passive:true});\n window.addEventListener(\"resize\",()=>{syncSearch();enhanceUnivershzrwBrand();setupUhzGooglePresentation()},{passive:true});\n}\nif(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",initialize,{once:true});\nelse initialize();\n})();";
